'use client';

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  type ReactNode,
} from 'react';
import { useAuth } from '@/contexts/AuthContext';
import type { AppNotification } from '@/types';
import { playNotificationSound } from '@/lib/sounds';
import { authFetch } from '@/lib/api-fetch';
import { toast } from 'sonner';
import {
  NOTIFICATION_POLL_INTERVAL_MS,
  FOREGROUND_STALE_THRESHOLD_MS,
  shouldPollNow,
  shouldRefreshOnForeground,
} from '@/lib/polling-policy';
import { mergeIncomingNotifications } from '@/lib/notifications/client-merge';

// ══════════════════════════════════════════════════════════════
//  Types
// ══════════════════════════════════════════════════════════════
interface NotificationContextValue {
  /** All loaded notifications (newest first) */
  notifications: AppNotification[];
  /** Unread count */
  unreadCount: number;
  /** Loading state for initial fetch */
  loading: boolean;
  /** Mark single notification as read (updates server + local state) */
  markRead: (id: string) => Promise<void>;
  /** Mark single notification as read without server call (optimistic local) */
  markReadLocal: (id: string) => void;
  /** Mark all as read */
  markAllRead: () => Promise<void>;
  /**
   * §NOTIFICATIONS-UX — optimistic mark-all: zero the badge + mark
   * loaded items read LOCALLY (no server call). The caller performs
   * the single authoritative POST; on failure it reconciles via
   * refresh().
   */
  markAllReadLocal: () => void;
  /** Refresh notifications from server */
  refresh: () => Promise<void>;
  /** Remove a notification locally (after delete) */
  removeLocal: (id: string) => void;
  /** Delete notification from server + local */
  deleteNotification: (id: string) => Promise<void>;
  /** Update a notification locally (after patch) */
  updateLocal: (id: string, updates: Partial<AppNotification>) => void;
  /** Add a new notification locally (from real-time listener) */
  addLocal: (notif: AppNotification) => void;
  /** Last notification received via real-time (for header pulse animation) */
  latestNotification: AppNotification | null;
  /** Whether the context is in an error state */
  error: boolean;
}

const NotificationContext = createContext<NotificationContextValue | null>(null);

export function useNotificationContext() {
  const ctx = useContext(NotificationContext);
  if (!ctx) throw new Error('useNotificationContext must be used within NotificationProvider');
  return ctx;
}

// ══════════════════════════════════════════════════════════════
//  Desktop Notification helpers
// ══════════════════════════════════════════════════════════════
async function requestDesktopPermission(): Promise<boolean> {
  if (typeof window === 'undefined' || !('Notification' in window)) return false;
  if (Notification.permission === 'granted') return true;
  if (Notification.permission === 'denied') return false;
  const result = await Notification.requestPermission();
  return result === 'granted';
}

function sendDesktopNotification(title: string, body: string, priority: string) {
  if (typeof window === 'undefined' || !('Notification' in window)) return;
  if (Notification.permission !== 'granted') return;
  try {
    const n = new Notification(title, {
      body,
      icon: '/favicon.ico',
      tag: `arm-notif-${Date.now()}`,
      requireInteraction: priority === 'critical',
    });
    n.onclick = () => {
      window.focus();
      n.close();
    };
    setTimeout(() => n.close(), priority === 'critical' ? 15000 : 8000);
  } catch {
    // Desktop notifications not available
  }
}

// ══════════════════════════════════════════════════════════════
//  Priority → Sound mapping
// ══════════════════════════════════════════════════════════════
function getSoundForPriority(priority: string): 'travel' | 'request' | 'success' | 'error' {
  switch (priority) {
    case 'critical':
    case 'high':
      return 'error';
    default:
      return 'request';
  }
}

// ══════════════════════════════════════════════════════════════
//  Priority → Toast style
// ══════════════════════════════════════════════════════════════
function showToastForNotification(notif: AppNotification) {
  const isCritical = notif.priority === 'critical';
  const isHigh = notif.priority === 'high';

  toast(notif.title, {
    description: notif.description?.slice(0, 120) + (notif.description?.length > 120 ? '...' : ''),
    duration: isCritical ? 8000 : isHigh ? 6000 : 4000,
    ...(isCritical && {
      className: '!bg-red-500/15 !border-red-500/30 !text-red-400',
    }),
  });
}

// ══════════════════════════════════════════════════════════════
//  Helper: trigger sound + toast + desktop notification for a new alert
// ══════════════════════════════════════════════════════════════
function triggerNewAlertEffects(notif: AppNotification, desktopGranted: boolean) {
  // 1. Toast for ALL new notifications
  showToastForNotification(notif);

  // 2. Sound for ALL priorities (different sounds per priority)
  playNotificationSound(getSoundForPriority(notif.priority));

  // 3. Desktop notification for critical + high
  if (desktopGranted && (notif.priority === 'critical' || notif.priority === 'high')) {
    sendDesktopNotification(notif.title, notif.description || '', notif.priority);
  }
}

// ══════════════════════════════════════════════════════════════
//  Provider
// ══════════════════════════════════════════════════════════════
export function NotificationProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [latestNotification, setLatestNotification] = useState<AppNotification | null>(null);
  const seenIdsRef = useRef<Set<string>>(new Set());
  const desktopPermissionRef = useRef(false);
  const lastFetchCountRef = useRef<number>(0);
  // Ref to avoid re-running effects when user object reference changes
  const userRef = useRef(user);

  useEffect(() => {
    userRef.current = user;
  }, [user]);

  // ── Request desktop notification permission once ──
  useEffect(() => {
    if (userRef.current) {
      requestDesktopPermission().then((granted) => {
        desktopPermissionRef.current = granted;
      });
    }
  }, [!!user]); // Stable boolean — doesn't re-fire on user object recreation

  // ── §16 unread-count accounting ── the badge is a real number that
  // reacts to every transition (server refresh, mark read, mark all,
  // delete, new arrival). The server count is authoritative; local
  // transitions adjust it so the badge never goes stale between
  // refreshes. Declared BEFORE refresh() (declaration order).
  const [serverUnreadCount, setServerUnreadCount] = useState<number | null>(null);
  const adjustUnread = useCallback((delta: number) => {
    setServerUnreadCount((prev) => (prev === null ? prev : Math.max(0, prev + delta)));
  }, []);

  // ── Fetch notifications and detect new ones (used for both initial + polling) ──
  const lastFetchAtRef = useRef<number>(0);
  // §OVERLAP-GUARD — an interval tick + foreground event + manual refresh
  // can all land while one fetch is still in flight; the guard turns the
  // later callers into no-ops so identical requests never overlap.
  const refreshInFlightRef = useRef(false);

  const refresh = useCallback(async () => {
    if (refreshInFlightRef.current) return;
    refreshInFlightRef.current = true;
    try {
      lastFetchAtRef.current = Date.now();
      // §16 — unread feed WITHOUT a 24h window: the badge must reflect
      // every unread notification the viewer can see. The server also
      // returns the authoritative `unreadCount` (computed over ALL
      // visible notifications, beyond any limit) and the badge uses it.
      const res = await authFetch('/api/notifications?limit=50&status=unread');
      if (res.ok) {
        const json = await res.json();
        const data: AppNotification[] = json.data || [];
        if (typeof json.unreadCount === 'number') {
          setServerUnreadCount(json.unreadCount);
        }

        setNotifications((prev) => {
          // §DEDUP — ID-based merge (see client-merge): a notification
          // already shown is never duplicated, whichever channel
          // delivered it (this poll or the realtime listener).
          const { merged, added } = mergeIncomingNotifications(prev, data);

          // Detect genuinely new notifications (not seen before)
          const newNotifs = added.filter((d) => !seenIdsRef.current.has(d.id));

          // Merge: new data first, then existing
          merged.forEach((n) => seenIdsRef.current.add(n.id));
          const result = merged;

          // If this is a polling round (not initial load) and we found new notifications
          if (newNotifs.length > 0 && lastFetchCountRef.current > 0) {
            // Process new notifications: sound + toast + desktop
            newNotifs.forEach((notif) => {
              // Only alert for very recent notifications (< 2 min old) to avoid alerting on old data
              const age = Date.now() - new Date(notif.createdAt).getTime();
              if (age < 120000) {
                triggerNewAlertEffects(notif, desktopPermissionRef.current);
              }
            });

            // Set latest for pulse animation
            setLatestNotification(newNotifs[0]);
            setTimeout(() => setLatestNotification(null), 3000);
          }

          lastFetchCountRef.current = result.length;
          return result;
        });
      } else {
        console.warn('[NotificationProvider] refresh() got non-ok response:', res.status);
      }
    } catch (err) {
      console.error('[NotificationProvider] refresh() error:', err);
      setError(true);
    } finally {
      refreshInFlightRef.current = false;
      setLoading(false);
    }
  }, []);

  // ── Initial fetch on login ──
  useEffect(() => {
    if (userRef.current) {
      refresh();
    }
  }, [!!user, refresh]); // !!user is stable boolean

  // ── Authenticated polling — the ONLY notification delivery path ──
  // §PHASE0-RTDB-RULES: the previous direct Firebase RTDB listener on
  // erp/notifications was REMOVED. RTDB rules cascade parent→child and
  // a root ".read": false cannot be re-granted at a child path, so the
  // only rules-compatible options were a world-readable notifications
  // path (every browser client could read EVERY employee's
  // notifications, directed or broadcast — unacceptable) or deny-all.
  // Deny-all was chosen; delivery is the EXISTING authenticated
  // /api/notifications poll, which filters recipients server-side
  // (lib/notifications/recipient-visibility). Nothing is lost
  // functionally: the poll already performed the same alerting as the
  // listener (sound + toast + desktop, below), reconciles anything
  // missed while disconnected via the foreground refresh, and the
  // listener had its own silent-degradation path. Re-introducing
  // real-time push requires per-recipient RTDB paths or Firebase
  // Auth custom tokens — a separate approved phase.
  // Uses !!user to avoid re-creating polling on every user object change
  useEffect(() => {
    if (!userRef.current) return;

    let cancelled = false;

    // 45s cadence, but it no longer fires while the tab is hidden,
    // and returning to the foreground refreshes once when the last
    // fetch is stale (polling-policy).
    const tick = () => {
      if (
        !cancelled &&
        shouldPollNow({
          isVisible: !document.hidden,
          lastPollAt: lastFetchAtRef.current || null,
          now: Date.now(),
          intervalMs: NOTIFICATION_POLL_INTERVAL_MS,
        })
      ) {
        refresh();
      }
    };
    const pollInterval = setInterval(tick, NOTIFICATION_POLL_INTERVAL_MS);

    // Foreground recovery: one refresh on tab return when stale
    const onVisibilityChange = () => {
      if (cancelled || document.hidden) return;
      if (
        shouldRefreshOnForeground({
          lastFetchAt: lastFetchAtRef.current || null,
          now: Date.now(),
          staleThresholdMs: FOREGROUND_STALE_THRESHOLD_MS,
        })
      ) {
        refresh();
      }
    };
    document.addEventListener('visibilitychange', onVisibilityChange);

    return () => {
      cancelled = true;
      clearInterval(pollInterval);
      document.removeEventListener('visibilitychange', onVisibilityChange);
    };
  }, [!!user, refresh]); // !!user prevents polling recreation churn

  // ── Mark read (server + local) ──
  const markReadLocal = useCallback((id: string) => {
    const target = notifications.find((n) => n.id === id);
    if (target && target.status === 'unread') adjustUnread(-1);
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, status: 'read' as const, readAt: n.readAt || new Date().toISOString() } : n))
    );
  }, [notifications, adjustUnread]);

  const markRead = useCallback(async (id: string) => {
    try {
      await authFetch(`/api/notifications/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'read' }),
      });
    } catch {
      // Silently fail
    }
    markReadLocal(id);
  }, [markReadLocal]);

  // ── Mark all read ── (single server call + badge reset)
  const markAllRead = useCallback(async () => {
    try {
      await authFetch('/api/notifications/mark-all-read', { method: 'POST' });
    } catch {
      // fall through to per-item marking as before
    }
    const unreadIds = notifications.filter((n) => n.status === 'unread').map((n) => n.id);
    unreadIds.forEach((id) => markReadLocal(id));
    setServerUnreadCount(0);
  }, [notifications, markReadLocal]);

  // ── Optimistic mark-all (local only — see interface doc) ──
  const markAllReadLocal = useCallback(() => {
    setNotifications((prev) =>
      prev.map((n) =>
        n.status === 'unread'
          ? { ...n, status: 'read' as const, readAt: n.readAt || new Date().toISOString() }
          : n,
      ),
    );
    setServerUnreadCount(0);
  }, []);

  // ── Remove local ──
  const removeLocal = useCallback((id: string) => {
    const target = notifications.find((n) => n.id === id);
    if (target && target.status === 'unread') adjustUnread(-1);
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, [notifications, adjustUnread]);

  // ── Delete notification (server + local) ──
  const deleteNotification = useCallback(async (id: string) => {
    try {
      await authFetch(`/api/notifications/${id}`, { method: 'DELETE' });
    } catch {
      // Silently fail
    }
    removeLocal(id);
  }, [removeLocal]);

  // ── Update local ──
  const updateLocal = useCallback((id: string, updates: Partial<AppNotification>) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, ...updates } : n))
    );
  }, []);

  // ── Add local (from listener) ──
  const addLocal = useCallback((notif: AppNotification) => {
    if (notifications.some((n) => n.id === notif.id)) return;
    seenIdsRef.current.add(notif.id);
    if (notif.status === 'unread') adjustUnread(1);
    setNotifications((prev) => [notif, ...prev].slice(0, 100));
    setLatestNotification(notif);
    setTimeout(() => setLatestNotification(null), 3000);
  }, [notifications, adjustUnread]);

  // Server count (authoritative, covers >50 unread) — falls back to
  // the local derivation before the first server response arrives.
  const unreadCount = serverUnreadCount ?? notifications.filter(n => n.status === 'unread').length;

  return (
    <NotificationContext.Provider
      value={{
        notifications,
        unreadCount,
        loading,
        markRead,
        markReadLocal,
        markAllRead,
        markAllReadLocal,
        refresh,
        removeLocal,
        deleteNotification,
        updateLocal,
        addLocal,
        latestNotification,
        error,
      }}
    >
      {children}
    </NotificationContext.Provider>
  );
}
